{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2175-07-23 01:00:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. You're in the hospital now. Can you tell me your name?"
    },
    {
      "turn_number": 2,
      "time": "2175-07-23 01:02:00",
      "speaker": "Patient",
      "text": "Yeah… it's James. What’s going on? I was just on the couch."
    },
    {
      "turn_number": 3,
      "time": "2175-07-23 01:04:00",
      "speaker": "Doctor",
      "text": "You were found unresponsive earlier. We know you’ve been drinking and may have taken something else. Your oxygen was low and you have pneumonia. We’re keeping you for treatment."
    },
    {
      "turn_number": 4,
      "time": "2175-07-23 01:06:00",
      "speaker": "Patient",
      "text": "Pneumonia again? I just got told I had that yesterday. I need my meds though. I’m on methadone."
    },
    {
      "turn_number": 5,
      "time": "2175-07-23 01:08:00",
      "speaker": "Doctor",
      "text": "We checked with your doctor. He hasn’t prescribed methadone in a month because your urine tests have been negative. We can’t give it now."
    },
    {
      "turn_number": 6,
      "time": "2175-07-23 01:10:00",
      "speaker": "Patient",
      "text": "What? That’s bullshit! I need it. I’m in pain. I’m leaving then."
    },
    {
      "turn_number": 7,
      "time": "2175-07-23 01:12:00",
      "speaker": "Doctor",
      "text": "I understand you’re upset, but you’re very sick. Your oxygen dropped this morning, and you’re not well enough to leave."
    },
    {
      "turn_number": 8,
      "time": "2175-07-23 01:14:00",
      "speaker": "Patient",
      "text": "I don’t care. I’m getting out of here."
    },
    {
      "turn_number": 9,
      "time": "2175-07-23 01:16:00",
      "speaker": "Doctor",
      "text": "You pulled out your IV. Security is here to help keep you safe. We’re not restraining you, but we need to make sure you don’t hurt yourself."
    },
    {
      "turn_number": 10,
      "time": "2175-07-23 01:18:00",
      "speaker": "Patient",
      "text": "I’m not staying if you won’t help my pain."
    },
    {
      "turn_number": 11,
      "time": "2175-07-23 01:20:00",
      "speaker": "Doctor",
      "text": "We’re helping your pain with other safe options. But methadone isn’t safe for you right now. Let’s focus on your pneumonia and breathing."
    },
    {
      "turn_number": 12,
      "time": "2175-07-23 01:22:00",
      "speaker": "Patient",
      "text": "Fine. But I’m not doing any more tests."
    },
    {
      "turn_number": 13,
      "time": "2175-07-23 06:00:00",
      "speaker": "Doctor",
      "text": "Good morning, James. Your oxygen was low again this morning—87%—so we put you on more oxygen. It’s better now at 95% on nasal cannula."
    },
    {
      "turn_number": 14,
      "time": "2175-07-23 06:02:00",
      "speaker": "Patient",
      "text": "I felt short of breath. Is it the pneumonia?"
    },
    {
      "turn_number": 15,
      "time": "2175-07-23 06:04:00",
      "speaker": "Doctor",
      "text": "Partly. Your chest X-ray shows improvement in the infection, but we’re concerned it’s not the only issue. The team wanted to do a CT scan to check for a blood clot, but you refused."
    },
    {
      "turn_number": 16,
      "time": "2175-07-23 06:06:00",
      "speaker": "Patient",
      "text": "I don’t want more scans. I’ve had enough. Is the antibiotic working?"
    },
    {
      "turn_number": 17,
      "time": "2175-07-23 06:08:00",
      "speaker": "Doctor",
      "text": "You got levofloxacin in the ER, but last time you were here, the infection was resistant to it. So we’ve switched you to Bactrim, which should work better based on your sputum culture."
    },
    {
      "turn_number": 18,
      "time": "2175-07-23 06:10:00",
      "speaker": "Patient",
      "text": "So I’m on new antibiotics now?"
    },
    {
      "turn_number": 19,
      "time": "2175-07-23 06:12:00",
      "speaker": "Doctor",
      "text": "Yes, twice a day. We also think your COPD might be flaring. We offered breathing treatments, but you declined."
    },
    {
      "turn_number": 20,
      "time": "2175-07-23 06:14:00",
      "speaker": "Patient",
      "text": "I hate those nebs. They make me shaky."
    },
    {
      "turn_number": 21,
      "time": "2175-07-23 06:16:00",
      "speaker": "Doctor",
      "text": "I understand. But they help open your airways. Maybe we can try a lower dose?"
    },
    {
      "turn_number": 22,
      "time": "2175-07-23 06:18:00",
      "speaker": "Patient",
      "text": "Not right now. Maybe later."
    },
    {
      "turn_number": 23,
      "time": "2175-07-23 10:00:00",
      "speaker": "Doctor",
      "text": "James, your labs show high sodium and high bicarbonate. That’s from dehydration and possibly from drinking a lot and not eating. Your liver enzymes are also a bit high, which is common with alcohol use."
    },
    {
      "turn_number": 24,
      "time": "2175-07-23 10:02:00",
      "speaker": "Patient",
      "text": "Am I in liver failure?"
    },
    {
      "turn_number": 25,
      "time": "2175-07-23 10:04:00",
      "speaker": "Doctor",
      "text": "No, not at all. But it’s a sign your body is under stress from alcohol. We’re giving you fluids and monitoring you."
    },
    {
      "turn_number": 26,
      "time": "2175-07-23 10:06:00",
      "speaker": "Patient",
      "text": "I know I drink. But I can’t stop here. I need to get back."
    },
    {
      "turn_number": 27,
      "time": "2175-07-23 10:08:00",
      "speaker": "Doctor",
      "text": "You’re going through alcohol withdrawal. That’s why we’re giving you diazepam every few hours. You’ve had 60 mg in the last 24 hours. Stopping suddenly could cause seizures."
    },
    {
      "turn_number": 28,
      "time": "2175-07-23 10:10:00",
      "speaker": "Patient",
      "text": "I’ve done it before. I’ll be fine."
    },
    {
      "turn_number": 29,
      "time": "2175-07-23 10:12:00",
      "speaker": "Doctor",
      "text": "This time is different. You’re weaker, and your body is fighting infection. Leaving now is risky."
    },
    {
      "turn_number": 30,
      "time": "2175-07-23 14:00:00",
      "speaker": "Doctor",
      "text": "We also offered nicotine patches since you smoke, but you declined."
    },
    {
      "turn_number": 31,
      "time": "2175-07-23 14:02:00",
      "speaker": "Patient",
      "text": "I don’t need help quitting. I’ve got bigger problems."
    },
    {
      "turn_number": 32,
      "time": "2175-07-23 14:04:00",
      "speaker": "Doctor",
      "text": "We also asked if you’d speak with a social worker about housing and support. You said no."
    },
    {
      "turn_number": 33,
      "time": "2175-07-23 14:06:00",
      "speaker": "Patient",
      "text": "What’s the point? Nobody helps anyway."
    },
    {
      "turn_number": 34,
      "time": "2175-07-24 08:00:00",
      "speaker": "Doctor",
      "text": "James, you’ve been here two days. Your pneumonia is improving, but you’ve only had two doses of the right antibiotic. You really should stay for at least five days."
    },
    {
      "turn_number": 35,
      "time": "2175-07-24 08:02:00",
      "speaker": "Patient",
      "text": "I’m leaving. I can’t stay here anymore. I feel better."
    },
    {
      "turn_number": 36,
      "time": "2175-07-24 08:04:00",
      "speaker": "Doctor",
      "text": "I have to tell you, leaving AMA—against medical advice—means you’re at high risk of getting worse, maybe even dying."
    },
    {
      "turn_number": 37,
      "time": "2175-07-24 08:06:00",
      "speaker": "Patient",
      "text": "I know. But I’m going. I’ll take the pills with me."
    },
    {
      "turn_number": 38,
      "time": "2175-07-24 08:08:00",
      "speaker": "Doctor",
      "text": "We can give you a prescription for Bactrim. But please, if you start feeling worse—short of breath, fever, confusion—come back right away."
    },
    {
      "turn_number": 39,
      "time": "2175-07-24 08:10:00",
      "speaker": "Patient",
      "text": "Yeah, I’ll think about it."
    },
    {
      "turn_number": 40,
      "time": "2175-07-24 08:12:00",
      "speaker": "Doctor",
      "text": "I’ll have the nurse give you discharge papers. Please take care of yourself, James."
    },
    {
      "turn_number": 41,
      "time": "2175-07-24 08:14:00",
      "speaker": "Patient",
      "text": "Thanks… for trying."
    },
    {
      "turn_number": 42,
      "time": "2175-07-24 08:16:00",
      "speaker": "Doctor",
      "text": "We care about your health. If you change your mind, we’re here."
    },
    {
      "turn_number": 43,
      "time": "2175-07-24 08:18:00",
      "speaker": "Patient",
      "text": "I’ll be okay."
    },
    {
      "turn_number": 44,
      "time": "2175-07-24 08:20:00",
      "speaker": "Doctor",
      "text": "Take this prescription and the contact for the clinic. Please follow up."
    },
    {
      "turn_number": 45,
      "time": "2175-07-24 08:22:00",
      "speaker": "Patient",
      "text": "Got it."
    },
    {
      "turn_number": 46,
      "time": "2175-07-24 08:24:00",
      "speaker": "Doctor",
      "text": "You’re officially leaving against medical advice. We’ve documented that you understand the risks."
    },
    {
      "turn_number": 47,
      "time": "2175-07-24 08:26:00",
      "speaker": "Patient",
      "text": "I understand."
    },
    {
      "turn_number": 48,
      "time": "2175-07-24 08:28:00",
      "speaker": "Doctor",
      "text": "Take care, James."
    },
    {
      "turn_number": 49,
      "time": "2175-07-24 08:30:00",
      "speaker": "Patient",
      "text": "Yeah. Bye."
    },
    {
      "turn_number": 50,
      "time": "2175-07-24 08:32:00",
      "speaker": "Doctor",
      "text": "Nurse will assist you with discharge."
    }
  ],
  "summary": {
    "admission_start": "2175-07-23 00:38:00",
    "admission_end": "2175-07-24 12:22:00",
    "summary_paragraph": "James, a man with a history of heavy alcohol use, COPD, and chronic pain from prior injuries, was admitted after being found unresponsive on a sofa. He presented with pneumonia, alcohol and benzodiazepine intoxication, and hypoxia. He received initial treatment with levofloxacin and flagyl in the ED, but due to prior resistance, was switched to Bactrim. He refused further testing, including a CT for possible pulmonary embolism, and declined breathing treatments, nicotine replacement, and social work support. He was treated for alcohol withdrawal with diazepam and showed some improvement in oxygen levels. Despite medical advice, he chose to leave the hospital against medical advice on the second day of admission, after receiving only two days of appropriate antibiotic therapy.",
    "problems": [
      "Other Staphylococcus pneumonia",
      "Alcohol withdrawal",
      "Obstructive chronic bronchitis with (acute) exacerbation",
      "Tobacco use disorder",
      "Lack of housing",
      "Acute alcoholic intoxication in alcoholism, continuous",
      "Chronic pain due to trauma",
      "Sedative, hypnotic or anxiolytic abuse, unspecified"
    ]
  }
}
